import sys
from itertools import permutations

data = sys.stdin.read().split()
s, t = data[0], data[1]
V = set('aeiou')
cs = {}
for ch in s:
    cs[ch] = cs.get(ch, 0) + 1
ct = {}
for ch in t:
    ct[ch] = ct.get(ch, 0) + 1
surplus, deficit = [], []
for ch in set(cs) | set(ct):
    diff = cs.get(ch, 0) - ct.get(ch, 0)
    if diff > 0:
        surplus += [ch] * diff
    elif diff < 0:
        deficit += [ch] * (-diff)

def cost(x, y):
    return 1 if (x in V) != (y in V) else 2

best = 0 if not surplus else min(sum(cost(x, y) for x, y in zip(surplus, p)) for p in permutations(deficit))
print(best)

